questionvariables.text:
/* Pool rows: [id, P, Q, context, category, explanation], in four groups. */
poolA: [
 ["A1", "\\(x = 3\\)", "\\(x^2 = 9\\)", "\\(x\\) is a real number", pimp, "If \\(x = 3\\) then \\(x^2 = 9\\), so \\(P \\Rightarrow Q\\). But \\(x = -3\\) gives \\(x^2 = 9\\) with \\(x \\neq 3\\), so \\(Q \\Rightarrow P\\) is false."],
 ["A2", "\\(n\\) is divisible by \\(4\\)", "\\(n\\) is even", "\\(n\\) is an integer", pimp, "If \\(n = 4m\\) then \\(n = 2(2m)\\), which is even, so \\(P \\Rightarrow Q\\). But \\(2\\) is even and not divisible by \\(4\\), so \\(Q \\Rightarrow P\\) is false."],
 ["A3", "\\(x \\gt 2\\)", "\\(x^2 \\gt 4\\)", "\\(x\\) is a real number", pimp, "If \\(x \\gt 2\\) then \\(x^2 \\gt 4\\), so \\(P \\Rightarrow Q\\). But \\(x = -3\\) gives \\(x^2 = 9 \\gt 4\\) with \\(x \\lt 2\\), so \\(Q \\Rightarrow P\\) is false."],
 ["A4", "\\(a \\in \\mathbb{Z}\\)", "\\(a \\in \\mathbb{Q}\\)", "\\(a\\) is a real number", pimp, "Every integer \\(a\\) is a rational number, \\(\\dfrac{a}{1}\\), so \\(P \\Rightarrow Q\\). But \\(\\dfrac{1}{2}\\) is rational and not an integer, so \\(Q \\Rightarrow P\\) is false."],
 ["A5", "triangle \\(ABC\\) is equilateral", "triangle \\(ABC\\) is isosceles (has at least two equal sides)", "\\(ABC\\) is a triangle", pimp, "An equilateral triangle has two (indeed three) equal sides, so \\(P \\Rightarrow Q\\). But a triangle with sides \\(2\\), \\(2\\) and \\(3\\) is isosceles and not equilateral, so \\(Q \\Rightarrow P\\) is false."]
];
poolB: [
 ["B1", "\\(ABCD\\) is a rectangle", "\\(ABCD\\) is a square", "\\(ABCD\\) is a quadrilateral", qimp, "Every square is a rectangle, so \\(Q \\Rightarrow P\\). But a \\(1\\) by \\(2\\) rectangle is not a square, so \\(P \\Rightarrow Q\\) is false."],
 ["B2", "\\(xy = 0\\)", "\\(x = 0\\)", "\\(x\\) and \\(y\\) are real numbers", qimp, "If \\(x = 0\\) then \\(xy = 0\\), so \\(Q \\Rightarrow P\\). But \\(x = 1\\), \\(y = 0\\) gives \\(xy = 0\\) with \\(x \\neq 0\\), so \\(P \\Rightarrow Q\\) is false."],
 ["B3", "\\(x \\lt 1\\)", "\\(x^2 \\lt 1\\)", "\\(x\\) is a real number", qimp, "If \\(x^2 \\lt 1\\) then \\(-1 \\lt x \\lt 1\\), so \\(x \\lt 1\\): \\(Q \\Rightarrow P\\). But \\(x = -2\\) is less than \\(1\\) and \\(x^2 = 4\\), so \\(P \\Rightarrow Q\\) is false."],
 ["B4", "\\(n\\) is divisible by \\(4\\) and by \\(6\\)", "\\(n\\) is divisible by \\(24\\)", "\\(n\\) is an integer", qimp, "If \\(n = 24m\\) then \\(n = 4(6m) = 6(4m)\\), so \\(Q \\Rightarrow P\\). But \\(12\\) is divisible by \\(4\\) and by \\(6\\) and not by \\(24\\), so \\(P \\Rightarrow Q\\) is false."],
 ["B5", "\\(n\\) is odd", "\\(n\\) is a prime number greater than \\(2\\)", "\\(n\\) is an integer", qimp, "A prime greater than \\(2\\) is not divisible by \\(2\\), so it is odd: \\(Q \\Rightarrow P\\). But \\(9\\) is odd and not prime, so \\(P \\Rightarrow Q\\) is false."]
];
poolC: [
 ["C1", "\\(x^2 = 9\\)", "\\(x = 3\\) or \\(x = -3\\)", "\\(x\\) is a real number", both, "If \\(x^2 = 9\\) then \\((x - 3)(x + 3) = 0\\), so \\(x = 3\\) or \\(x = -3\\); and \\(3^2 = (-3)^2 = 9\\). So \\(P \\Leftrightarrow Q\\)."],
 ["C2", "\\(n\\) is even", "\\(n^2\\) is even", "\\(n\\) is an integer", both, "If \\(n = 2k\\) then \\(n^2 = 2(2k^2)\\), so \\(P \\Rightarrow Q\\). If \\(n\\) is odd, \\(n = 2k + 1\\), then \\(n^2 = 2(2k^2 + 2k) + 1\\) is odd; so if \\(n^2\\) is even, \\(n\\) cannot be odd: \\(Q \\Rightarrow P\\). So \\(P \\Leftrightarrow Q\\)."],
 ["C3", "\\(n\\) is divisible by \\(6\\)", "\\(n\\) is divisible by \\(2\\) and by \\(3\\)", "\\(n\\) is an integer", both, "If \\(n = 6m\\) then \\(n = 2(3m) = 3(2m)\\), so \\(P \\Rightarrow Q\\). A number divisible by \\(2\\) and by \\(3\\) is divisible by \\(6\\), because \\(2\\) and \\(3\\) have no common factor, so \\(Q \\Rightarrow P\\). So \\(P \\Leftrightarrow Q\\)."],
 ["C4", "\\(x + 1 = 4\\)", "\\(x = 3\\)", "\\(x\\) is a real number", both, "Subtracting \\(1\\) from both sides of \\(x + 1 = 4\\) gives \\(x = 3\\), and adding \\(1\\) to both sides of \\(x = 3\\) gives \\(x + 1 = 4\\). So \\(P \\Leftrightarrow Q\\)."],
 ["C5", "\\(2x \\gt 6\\)", "\\(x \\gt 3\\)", "\\(x\\) is a real number", both, "Dividing both sides of \\(2x \\gt 6\\) by the positive number \\(2\\) gives \\(x \\gt 3\\), and multiplying both sides of \\(x \\gt 3\\) by \\(2\\) gives \\(2x \\gt 6\\). So \\(P \\Leftrightarrow Q\\)."]
];
poolD: [
 ["D1", "\\(n\\) is a prime number", "\\(n\\) is odd", "\\(n\\) is an integer", neither, "\\(2\\) is prime and not odd, so \\(P \\Rightarrow Q\\) is false; \\(9\\) is odd and not prime, so \\(Q \\Rightarrow P\\) is false."],
 ["D2", "\\(n\\) is a multiple of \\(3\\)", "\\(n\\) is odd", "\\(n\\) is an integer", neither, "\\(6\\) is a multiple of \\(3\\) and not odd; \\(5\\) is odd and not a multiple of \\(3\\). Neither implication holds."],
 ["D3", "\\(x \\gt 1\\)", "\\(x^2 \\gt 4\\)", "\\(x\\) is a real number", neither, "\\(x = \\dfrac{3}{2}\\) has \\(x \\gt 1\\) but \\(x^2 = \\dfrac{9}{4} \\lt 4\\); \\(x = -3\\) has \\(x^2 = 9 \\gt 4\\) but \\(x \\lt 1\\). Neither implication holds."],
 ["D4", "\\(ABCD\\) has four equal sides", "\\(ABCD\\) has four right angles", "\\(ABCD\\) is a quadrilateral", neither, "A rhombus that is not a square has four equal sides and no right angles; a \\(1\\) by \\(2\\) rectangle has four right angles and unequal sides. Neither implication holds."],
 ["D5", "\\(n\\) is a multiple of \\(4\\)", "\\(n\\) is a multiple of \\(6\\)", "\\(n\\) is an integer", neither, "\\(4\\) is a multiple of \\(4\\) and not of \\(6\\); \\(6\\) is a multiple of \\(6\\) and not of \\(4\\). Neither implication holds."]
];
/* One row from groups A and B together, one from C, one from D, one more from the 17 left. */
rowAB: rand(append(poolA, poolB));
rowC: rand(poolC);
rowD: rand(poolD);
poolleft: sublist(append(poolA, poolB, poolC, poolD), lambda([rw], not(member(rw, [rowAB, rowC, rowD]))));
rowX: rand(poolleft);
qrows: random_permutation([rowAB, rowC, rowD, rowX]);
dd(c) := [[pimp, is(c = pimp), "P ⇒ Q, but not Q ⇒ P"], [qimp, is(c = qimp), "Q ⇒ P, but not P ⇒ Q"], [both, is(c = both), "P ⇔ Q"], [neither, is(c = neither), "neither"]];
diagof(c) := if c = pimp then both else pimp;
othrof(c) := if c = qimp then both else if c = both then neither else if c = neither then both else neither;
/* Wrong-answer feedback says what to test. It does not show the row's explanation, which names the right answer: that appears with a correct answer and in the worked solution. */
leaddiag(c) := if c = pimp then "An implication and its converse are different statements, and each needs its own check. Test the converse, \\(Q \\Rightarrow P\\): is there a case where \\(Q\\) is true and \\(P\\) is false?"
  else if c = qimp then "Check the direction. \\(P \\Rightarrow Q\\) says that whenever \\(P\\) is true, \\(Q\\) is true. Is there a case where \\(P\\) is true and \\(Q\\) is false? Then test \\(Q \\Rightarrow P\\) in the same way."
  else if c = both then "You have said that \\(Q \\Rightarrow P\\) is false. That needs a case where \\(Q\\) is true and \\(P\\) is false. Can you find one? If not, think about why there is none."
  else "You have said that \\(P \\Rightarrow Q\\) is true. Test it: is there a case where \\(P\\) is true and \\(Q\\) is false?";
leadothr: "Check each direction separately. Is there a case where \\(P\\) is true and \\(Q\\) is false? Is there one where \\(Q\\) is true and \\(P\\) is false?";
labans(c) := if c = pimp then "\\(P \\Rightarrow Q\\), but not \\(Q \\Rightarrow P\\)." else if c = qimp then "\\(Q \\Rightarrow P\\), but not \\(P \\Rightarrow Q\\)." else "";
P1: qrows[1][2]; Q1: qrows[1][3]; ctx1: qrows[1][4]; cor1: qrows[1][5]; expl1: qrows[1][6];
P2: qrows[2][2]; Q2: qrows[2][3]; ctx2: qrows[2][4]; cor2: qrows[2][5]; expl2: qrows[2][6];
P3: qrows[3][2]; Q3: qrows[3][3]; ctx3: qrows[3][4]; cor3: qrows[3][5]; expl3: qrows[3][6];
P4: qrows[4][2]; Q4: qrows[4][3]; ctx4: qrows[4][4]; cor4: qrows[4][5]; expl4: qrows[4][6];
ta1: dd(cor1); ta2: dd(cor2); ta3: dd(cor3); ta4: dd(cor4);
diag1: diagof(cor1); diag2: diagof(cor2); diag3: diagof(cor3); diag4: diagof(cor4);
othr1: othrof(cor1); othr2: othrof(cor2); othr3: othrof(cor3); othr4: othrof(cor4);
fbdiag1: leaddiag(cor1); fbothr1: leadothr;
fbdiag2: leaddiag(cor2); fbothr2: leadothr;
fbdiag3: leaddiag(cor3); fbothr3: leadothr;
fbdiag4: leaddiag(cor4); fbothr4: leadothr;
s_assert(is(length(unique([cor1, diag1, othr1])) = 3 and length(unique([cor2, diag2, othr2])) = 3 and length(unique([cor3, diag3, othr3])) = 3 and length(unique([cor4, diag4, othr4])) = 3), true);
